---@class vercel.connect.UnprocessableEntityError: distilled.Error
---@field tag "UnprocessableEntity"
---@field body? vercel.connect.ConnectError|string

---@class vercel.connect.Options
---@field token? string|distilled.Secret|fun(host: table): (string|distilled.Secret|nil, distilled.Error?) Required; default from $VERCEL_TOKEN
---@field base_url? string Default https://api.vercel.com (or $VERCEL_API_URL)
---@field host? table The host seams: transport, sleep, now, exec, random, getenv, epoch
---@field transport? fun(request: table): (table?, distilled.Error?)
---@field sleep? fun(seconds: number)
---@field now? fun(): number
---@field retry? string|table A retry preset or policy fields
---@field deadline_s? number Wall-clock budget for one call, sleeps included
---@field tracing? "off"|"operation"|"debug"|table
---@field validation? "lenient"|"additional"|"strict"
---@field [string] any

---@class vercel.connect.Module
local Module = {}

---@param options? vercel.connect.Options
---@return vercel.connect.Client
function Module.new(options) end

---@class vercel.connect.Client
local Client = {}

---A client sharing this one's budget, credentials cache and tracer, with overrides.
---@param options vercel.connect.Options
---@return vercel.connect.Client
function Client:with(options) end

---Flush spans and release what the client holds.
function Client:close() end

---Create a connector
---
---Create a connector and optionally link it to a project. Use `type` with complete provider data, or use `service` with `connectionMethod` so Connect can supply the type, endpoints, templates, and defaults.
---
---`POST /v1/connect/connectors`
---Errors: BadRequest, Forbidden, NotFound, Conflict, UnprocessableEntity.
---@param input vercel.connect.CreateConnectorRequest
---@return vercel.connect.ConnectConnectorCreateResult? value
---@return distilled.Error? err
function Client:create_connector(input) end

---Create a Connect authorization request
---
---Create an authorization request for a connector and return the URL and verifier details needed to complete the flow.
---
---`POST /v1/connect/authorize/{connector}`
---Errors: BadRequest, Forbidden, NotFound, Conflict, UnprocessableEntity.
---@param input vercel.connect.CreateConnectorAuthorizationRequestRequest
---@return vercel.connect.CreateConnectorAuthorizationRequestResponse? value
---@return distilled.Error? err
function Client:create_connector_authorization_request(input) end

---Delete a connector
---
---Delete a connector, its project connections, and its installation records.
---
---`DELETE /v1/connect/connectors/{connector}`
---Errors: BadRequest, Forbidden, NotFound, Conflict, UnprocessableEntity.
---@param input vercel.connect.DeleteConnectorRequest
---@return vercel.connect.DeleteConnectorResponse? value
---@return distilled.Error? err
function Client:delete_connector(input) end

---Disconnect a connector from a project
---
---Disconnect a connector from a project.
---
---`DELETE /v1/connect/connectors/{connector}/projects/{projectId}`
---Errors: BadRequest, Forbidden, NotFound, Conflict, UnprocessableEntity.
---@param input vercel.connect.DeleteConnectorProjectConnectionRequest
---@return vercel.connect.DeleteConnectorProjectConnectionResponse? value
---@return distilled.Error? err
function Client:delete_connector_project_connection(input) end

---Disconnect a connector from a project environment
---
---Remove a connector's access and event destinations for one project environment. Other environments, the connector, and its provider installations are preserved. Preview disconnect removes destinations for every preview branch in the project. Disconnecting the last environment also releases the project-local UID. Safe to retry.
---
---`DELETE /v1/connect/connectors/{connector}/projects/{projectId}/environments/{environment}`
---Errors: BadRequest, Forbidden, NotFound, Conflict, UnprocessableEntity.
---@param input vercel.connect.DisconnectConnectorProjectEnvironmentRequest
---@return vercel.connect.DisconnectConnectorProjectEnvironmentResponse? value
---@return distilled.Error? err
function Client:disconnect_connector_project_environment(input) end

---Eject a managed connector
---
---Disconnect a managed connector from its provider-side manager.
---
---`POST /v1/connect/connectors/{connector}/managed/eject`
---Errors: BadRequest, Forbidden, NotFound, Conflict, UnprocessableEntity.
---@param input vercel.connect.EjectManagedConnectorRequest
---@return vercel.connect.ConnectConnector? value
---@return distilled.Error? err
function Client:eject_managed_connector(input) end

---Get a connector
---
---Get the connector by ID. Accepts a dashboard/team requester or a deployment's project OIDC token; project requesters may only read connectors linked to their project and environment.
---
---`GET /v1/connect/connectors/{connector}`
---Errors: BadRequest, Forbidden, NotFound, Conflict, UnprocessableEntity.
---@param input vercel.connect.GetConnectorRequest
---@return vercel.connect.ConnectConnector? value
---@return distilled.Error? err
function Client:get_connector(input) end

